import {
    Table,
    ReferenceColumn,
    BooleanColumn,
    StringColumn,
    DecimalColumn,
    SystemClassNameColumn,
    DateColumn,
    GenericColumn,
    IntegerColumn,
    DomainPathColumn,
    DateTimeColumn,
    DomainIdColumn,
    GuidColumn,
} from '@servicenow/sdk/core'

export const ast_contract = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
    },
    autoNumber: {
        number: 10000,
        prefix: 'CNTR',
    },
    display: 'vendor_contract',
    extensible: true,
    label: 'Contract',
    name: 'ast_contract',
    schema: {
        vendor: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            cascadeRule: 'clear',
            label: [
                {
                    hint: 'Vendor of the contract',
                    label: 'Vendor',
                    plural: 'Vendors',
                    language: 'en',
                },
            ],
            referenceTable: 'core_company',
            referenceQual: 'vendor=true^EQ',
        }),
        renewable: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Indicates whether the contract includes the possibility for being renewed at the end of its term',
                    label: 'Automatically renew',
                    plural: 'Automatically renews',
                    language: 'en',
                },
            ],
        }),
        vendor_account: StringColumn({
            label: [
                {
                    hint: 'Vendor account with which the contract is associated',
                    label: 'Vendor account',
                    plural: 'Vendor accounts',
                    language: 'en',
                },
            ],
        }),
        cost_adjustment_percentage: DecimalColumn({
            attributes: {
                no_text_index: true,
            },
            default: '0',
            label: [
                {
                    hint: 'Percentage of cost change applied to the contract',
                    label: 'Cost adjustment percentage',
                    plural: 'Cost adjustment percentages',
                    language: 'en',
                },
            ],
            maxLength: 15,
        }),
        description: StringColumn({
            label: [
                {
                    hint: 'Detailed description of the contract',
                    label: 'Description',
                    plural: 'Descriptions',
                    language: 'en',
                },
            ],
            maxLength: 4000,
        }),
        cost_adjustment_type: StringColumn({
            attributes: {
                no_text_index: true,
            },
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Type of cost adjustment applied to the contract',
                    label: 'Cost adjustment type',
                    plural: 'Cost adjustment types',
                    language: 'en',
                },
            ],
        }),
        sys_class_name: SystemClassNameColumn({
            attributes: {
                no_text_index: true,
            },
            default: 'javascript:current.getTableName();',
            dropdown: 'dropdown_without_none',
            label: 'Contract type',
            maxLength: 80,
        }),
        ends: DateColumn({
            label: [
                {
                    hint: 'Date on which the contract expires',
                    label: 'End date',
                    plural: 'End dates',
                    language: 'en',
                },
            ],
        }),
        total_cost: GenericColumn({
            attributes: {
                no_text_index: true,
                omit_sys_original: true,
            },
            columnType: 'currency',
            default: '0',
            label: [
                {
                    hint: 'Final cost of the contract after adjustments have been applied',
                    label: 'Total cost',
                    plural: 'Total costs',
                    language: 'en',
                },
            ],
            maxLength: 20,
        }),
        tax_rate: DecimalColumn({
            attributes: {
                no_text_index: true,
            },
            default: "javascript:'7'+GlideLocale.get().getDecimalSeparator()+'75';",
            label: [
                {
                    hint: 'Tax rate to be applied to the total cost if applicable',
                    label: 'Effective tax rate',
                    plural: 'Effective tax rates',
                    language: 'en',
                },
            ],
            maxLength: 15,
        }),
        contract_model: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            cascadeRule: 'restrict',
            label: [
                {
                    hint: 'Type of contract being created such as Service or Purchase Agreement',
                    label: 'Contract model',
                    plural: 'Contract models',
                    language: 'en',
                },
            ],
            mandatory: true,
            referenceTable: 'cmdb_model',
            referenceQual: 'javascript:new ContractManagementUtils().getContractModels();',
        }),
        state: StringColumn({
            attributes: {
                ignore_filter_on_new: true,
            },
            default: 'draft',
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Current state of the contract',
                    label: 'State',
                    plural: 'States',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        expiration: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
                readonly_clickthrough: true,
            },
            cascadeRule: 'clear',
            label: [
                {
                    hint: 'Level of contract threshold breach if any occur',
                    label: 'Expiration',
                    plural: 'Expirations',
                    language: 'en',
                },
            ],
            referenceTable: 'clm_condition_checker',
        }),
        monthly_cost: GenericColumn({
            attributes: {
                no_text_index: true,
                omit_sys_original: true,
            },
            columnType: 'currency',
            default: '0',
            label: 'Monthly cost',
            maxLength: 20,
        }),
        payment_amount: GenericColumn({
            attributes: {
                no_text_index: true,
                omit_sys_original: true,
            },
            columnType: 'currency',
            default: '0',
            label: [
                {
                    hint: 'Amount which has been paid so far',
                    label: 'Payment amount',
                    plural: 'Payment amounts',
                    language: 'en',
                },
            ],
            maxLength: 20,
        }),
        renewal_end_date: DateColumn({
            label: [
                {
                    hint: 'Date on which the contract renewal ends',
                    label: 'Renewal end date',
                    plural: 'Renewal end dates',
                    language: 'en',
                },
            ],
        }),
        process: StringColumn({
            attributes: {
                no_text_index: true,
            },
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Current operational process being performed on contract(ie. Extension or Renewal)',
                    label: 'Process',
                    plural: 'Process',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        ratecard: BooleanColumn({
            label: [
                {
                    hint: 'Flag to identify if this contract is being controlled from rate cards',
                    label: 'Has rate card',
                    plural: 'Has rate cards',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        cost_per_unit: GenericColumn({
            attributes: {
                no_text_index: true,
                omit_sys_original: true,
            },
            columnType: 'currency',
            label: 'Cost per unit',
            maxLength: 20,
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                    language: 'en',
                },
            ],
        }),
        customer: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Customer',
            referenceTable: 'core_company',
            referenceQual: 'customer=true',
        }),
        payment_schedule: StringColumn({
            attributes: {
                no_text_index: true,
            },
            default: 'Monthly',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Schedule defining payments',
                    label: 'Payment schedule',
                    plural: 'Payment schedules',
                    language: 'en',
                },
            ],
        }),
        renewal_options: StringColumn({
            attributes: {
                no_text_index: true,
            },
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Renewal duration',
                    label: 'Options',
                    plural: 'Options',
                    language: 'en',
                },
            ],
        }),
        life_cycle_stage_status: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
            },
            label: 'Life Cycle Stage Status',
            maxLength: 40,
            referenceTable: 'life_cycle_stage_status',
            referenceKey: 'name',
            referenceQual: 'javascript: new LifeCycleUtil().filterLifeCycleStageStatus()',
        }),
        approval_history: GenericColumn({
            attributes: {
                no_text_index: true,
            },
            columnType: 'journal',
            label: 'Approval History',
            maxLength: 4000,
            readOnly: true,
            spellCheck: true,
        }),
        business_owner: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Internal contact responsible for the ownership of goods or services',
                    label: 'Business owner',
                    plural: 'Business owners',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                    language: 'en',
                },
            ],
        }),
        covers: StringColumn({
            label: 'Covers',
            maxLength: 4000,
        }),
        contract_administrator: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            cascadeRule: 'clear',
            label: [
                {
                    hint: 'Internal contact for reviewing, interpreting and signing contracts',
                    label: 'Contract administrator',
                    plural: 'Contract administrators',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
        }),
        cost_center: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
                readonly_clickthrough: true,
            },
            cascadeRule: 'clear',
            label: [
                {
                    hint: 'Cost center financially responsible for the asset',
                    label: 'Cost center',
                    plural: 'Cost centers',
                    language: 'en',
                },
            ],
            referenceTable: 'cmn_cost_center',
        }),
        license_type: StringColumn({
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'License classification',
                    label: 'Agreement type',
                    plural: 'Agreement types',
                    language: 'en',
                },
            ],
        }),
        commitment: GenericColumn({
            attributes: {
                no_text_index: true,
                omit_sys_original: true,
            },
            columnType: 'currency',
            label: [
                {
                    hint: "Amount we agree to spend with this vendor, during the purchase agreement's span",
                    label: 'Commitment',
                    plural: 'Commitments',
                    language: 'en',
                },
            ],
            maxLength: 20,
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                    language: 'en',
                },
            ],
        }),
        process_non_contractual_slas: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Allows the processing of SLA Definitions that aren’t associated with a Contract',
                    label: 'Process non-contractual SLAs',
                    plural: 'Process non-contractual SLAs',
                    language: 'en',
                },
            ],
        }),
        starts: DateColumn({
            label: [
                {
                    hint: 'Date on which the contract takes effect',
                    label: 'Start date',
                    plural: 'Start dates',
                    language: 'en',
                },
            ],
        }),
        sub_total_cost: GenericColumn({
            attributes: {
                no_text_index: true,
                omit_sys_original: true,
            },
            columnType: 'currency',
            default: '0',
            label: 'Sub total cost',
            maxLength: 20,
        }),
        number: StringColumn({
            default: 'javascript:getNextObjNumberPadded();',
            label: [
                {
                    hint: 'Internal unique number identifying the contract',
                    label: 'Number',
                    plural: 'Numbers',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        active: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Indicates whether the contract is currently in use',
                    label: 'Active',
                    plural: 'Active',
                    language: 'en',
                },
            ],
        }),
        sales_tax: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Indicates whether sales tax should be applied to the total cost',
                    label: 'Sales tax',
                    plural: 'Sales taxes',
                    language: 'en',
                },
            ],
        }),
        vendor_contract: StringColumn({
            label: [
                {
                    hint: 'Unique number identifying the contract, as assigned by the vendor',
                    label: 'Contract number',
                    plural: 'Contract numbers',
                    language: 'en',
                },
            ],
            mandatory: true,
        }),
        cost_adjustment: DecimalColumn({
            attributes: {
                no_text_index: true,
            },
            default: '0',
            label: [
                {
                    hint: 'Amount of cost change applied to the contract',
                    label: 'Cost adjustment amount',
                    plural: 'Cost adjustment amounts',
                    language: 'en',
                },
            ],
            maxLength: 15,
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        short_description: StringColumn({
            label: [
                {
                    hint: 'Short description of the contract',
                    label: 'Name',
                    plural: 'Names',
                    language: 'en',
                },
            ],
            maxLength: 100,
        }),
        cost_adjustment_reason: StringColumn({
            attributes: {
                no_text_index: true,
            },
            label: [
                {
                    hint: 'Justification for cost adjustment',
                    label: 'Cost adjustment reason',
                    plural: 'Cost adjustment reasons',
                    language: 'en',
                },
            ],
        }),
        location: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
                readonly_clickthrough: true,
            },
            cascadeRule: 'clear',
            label: [
                {
                    hint: 'Location covered by the contract',
                    label: 'Location',
                    plural: 'Locations',
                    language: 'en',
                },
            ],
            referenceTable: 'cmn_location',
        }),
        po_number: StringColumn({
            label: [
                {
                    hint: 'Purchase order under which the contract was purchased',
                    label: 'PO Number',
                    plural: 'PO Numbers',
                    language: 'en',
                },
            ],
        }),
        terms_and_conditions: GenericColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            columnType: 'translated_html',
            label: [
                {
                    hint: 'Legally binding terms and conditions of the contract',
                    label: 'Terms and conditions',
                    plural: 'Terms and conditions',
                    language: 'en',
                },
            ],
            maxLength: 10000,
            readOnly: true,
        }),
        discount: DecimalColumn({
            attributes: {
                no_text_index: true,
            },
            label: [
                {
                    hint: 'Discount this vendor will provide on products covered by this contract',
                    label: 'Discount',
                    plural: 'Discounts',
                    language: 'en',
                },
            ],
            maxLength: 15,
        }),
        applicable_taxes: StringColumn({
            attributes: {
                no_text_index: true,
            },
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Tax applicable to this contract',
                    label: 'Applicable taxes',
                    plural: 'Applicable taxes',
                    language: 'en',
                },
            ],
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                    language: 'en',
                },
            ],
        }),
        renewal_contact: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
                readonly_clickthrough: true,
            },
            cascadeRule: 'clear',
            label: [
                {
                    hint: 'Person to be contacted for contract renewal/extension on the vendor side',
                    label: 'Renewal/Extension contact',
                    plural: 'Renewal/Extension contacts',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
        }),
        license_quantity_entitled: IntegerColumn({
            attributes: {
                no_text_index: true,
            },
            label: [
                {
                    hint: 'Number of license rights granted by the contract, when applicable',
                    label: 'License quantity entitled',
                    plural: 'License quantity entitled',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the contract belongs',
                    label: 'Domain',
                    plural: 'Domains',
                    language: 'en',
                },
            ],
        }),
        yearly_cost: GenericColumn({
            attributes: {
                no_text_index: true,
                omit_sys_original: true,
            },
            columnType: 'currency',
            default: '0',
            label: 'Yearly cost',
            maxLength: 20,
        }),
        tax_exempt: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Indicates whether the contract is exempt from tax',
                    label: 'Tax exempt',
                    plural: 'Tax exempts',
                    language: 'en',
                },
            ],
        }),
        renewal_date: DateColumn({
            label: [
                {
                    hint: 'Date on which the contract renewal takes effect',
                    label: 'Renewal start date',
                    plural: 'Renewal start dates',
                    language: 'en',
                },
            ],
        }),
        substate: StringColumn({
            attributes: {
                ignore_filter_on_new: true,
                no_text_index: true,
            },
            default: 'awaiting_review',
            dropdown: 'dropdown_with_none',
            dependent: 'state',
            label: [
                {
                    hint: 'Current substate of the contract',
                    label: 'Substate',
                    plural: 'Substates',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        approver: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            cascadeRule: 'clear',
            label: [
                {
                    hint: 'Person who is responsible for reviewing the contract',
                    label: 'Approver',
                    plural: 'Approvers',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
            referenceQual: 'roles=contract_manager',
        }),
        lifetime_cost: GenericColumn({
            attributes: {
                no_text_index: true,
                omit_sys_original: true,
            },
            columnType: 'currency',
            label: 'Lifetime cost',
            maxLength: 20,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        tax_cost: GenericColumn({
            attributes: {
                no_text_index: true,
                omit_sys_original: true,
            },
            columnType: 'currency',
            label: [
                {
                    hint: 'Total cost of the tax',
                    label: 'Tax cost',
                    plural: 'Tax costs',
                    language: 'en',
                },
            ],
            maxLength: 20,
        }),
        invoice_payment_terms: StringColumn({
            attributes: {
                no_text_index: true,
            },
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Invoice payment terms of the contract',
                    label: 'Invoice payment terms',
                    plural: 'Invoice payment terms',
                    language: 'en',
                },
            ],
        }),
        life_cycle_stage: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
            },
            label: 'Life Cycle Stage',
            maxLength: 40,
            referenceTable: 'life_cycle_stage',
            referenceKey: 'name',
            referenceQual: 'javascript: new LifeCycleUtil().filterLifeCycleStage()',
        }),
        application_model: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
            },
            label: [
                {
                    hint: 'the application that this contract is used to support',
                    label: 'Application model',
                    plural: 'Application models',
                    language: 'en',
                },
            ],
            referenceTable: 'cmdb_application_product_model',
        }),
        parent_contract: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            cascadeRule: 'clear',
            label: [
                {
                    hint: 'Parent contract or agreement for this contract',
                    label: 'Parent contract',
                    plural: 'Parent contracts',
                    language: 'en',
                },
            ],
            referenceTable: 'ast_contract',
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
    },
    textIndex: true,
})
